<template>
  <div class="register">
    <Transition name="fade">
      <Calendar
        v-if="currentStep > 0"
        class="register-calendar"
        :availableDates="availableDates"
        @update:selectedDate="handleDateSelect"
      />
    </Transition>

    <div class="register__block">
      <div class="register-services" v-if="services.length > 0">
        <serviceBlock
          v-for="service in services"
          :key="service.id"
          :service="service"
          class="register-services__item"
          @plus="updateServiceCount(service, 'increment')"
          @minus="updateServiceCount(service, 'decrement')"
        >
          {{ service.id }}
        </serviceBlock>
      </div>

      <Transition name="fade">
        <regFrom v-if="selectedServices.length > 0" class="register-form" />
      </Transition>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref, computed } from "vue";
import Calendar from "@/components/v-calendar.vue";
import serviceBlock from "@/components/service-block.vue";
import regFrom from "@/components/reg-form.vue";
import { useStore } from "vuex";

const store = useStore();

const currentStep = ref(4);

const selectedDate = computed({
  get: () => store.state.selectedDate,
  set: (newValue) => (store.state.selectedDate = newValue),
});

const availableDates = ["2025-06-08", "2025-06-10", "2025-06-15"];

const availableServices = computed(() => store.state.availableServices);

const services = computed(() => {
  return availableServices.value[selectedDate.value] || [];
});

const selectedServices = computed(() => store.state.selectedServices);

function handleDateSelect(date: Date) {
  store.commit("setSelectedDate", date.toISOString().split("T")[0]);

  store.state.selectedServices = []
}

function nextStep() {
  if (currentStep.value < 4) {
    currentStep.value++;
  }
}
function updateServiceCount(service, action) {
  const serviceId = service.id;
  const selectedServices = store.state.selectedServices;

  const selectedService = selectedServices.find(
    (item) => item.service.id === serviceId
  );

  if (action === "increment") {
    if (selectedService) {
      selectedService.clientsCount++;
    } else {
      selectedServices.push({
        clientsCount: 1,
        service: service,
      });
    }
  } else if (action === "decrement") {
    if (selectedService) {
      if (selectedService.clientsCount > 1) {
        selectedService.clientsCount--;
      } else {
        const index = selectedServices.findIndex(
          (item) => item.service.id === serviceId
        );
        if (index !== -1) {
          selectedServices.splice(index, 1);
        }
      }
    }
  }
}

function submitForm() {
  console.log("Форма отправлена!");
}
</script>

<style scoped lang="scss">
.register {
  margin: 0 auto;
  padding: 20px;
  display: flex;
  gap: 20px;

  &__block {
    flex-grow: 1;

    display: flex;
    flex-direction: column;

    @media (max-width: 862px) {
      width: 100%;
      max-width: 500px;
    }
  }

  @media (max-width: 862px) {
    flex-direction: column;
    align-items: center;
  }
}

.register-services {
  display: flex;
  flex-direction: column;
  gap: 24px;
  align-items: center;

  width: 100%;

  margin-bottom: 20px;
}
.register-calendar {
  flex-grow: 1;
}

.register-form {
  flex-grow: 1;
}

@media (max-width: 560px) {
  .register {
    padding: 10px;
  }
}

.fade-enter-active,
.fade-leave-active {
  transition: opacity 0.2s ease;
}
.fade-enter-from,
.fade-leave-to {
  opacity: 0;
}
</style>
